// Conserver l'ordre du Concepteur, y compris après ajout ou déplacement de modalités.
function dashboardOrderedModalities(rows,structures=false){
 const rank=(row)=>{
  const n=Number(row?.Ordre);
  if(row?.Ordre!==null&&row?.Ordre!==undefined&&String(row.Ordre).trim()!==""&&Number.isFinite(n)&&(!structures||n>0))return n;
  if(structures){const fallback=Number(row?.manualSort);return Number.isFinite(fallback)?fallback:Number.MAX_SAFE_INTEGER;}
  return Number.MAX_SAFE_INTEGER;
 };
 return [...(rows||[])].sort((a,b)=>rank(a)-rank(b));
}
function questionChoiceLabels(q){
  const out=new Map(),def=state.definition||{},qc=String(codeOf(q?.Question_Code)||"");
  for(const c of dashboardOrderedModalities(def.choices||[])){
    if(String(resolveRefCode(c.Question_Code,def.questions||[],"Question_Code"))!==qc)continue;
    const k=String(codeOf(c.Choix_Code)||"");
    if(k)out.set(k,String(first(c,["Libelle","Libellé","Valeur","Choix_Code"],k)));
  }
  const rc=resolveRefCode(q?.Referentiel_Code,def.referentials||[],"Referentiel_Code");
  if(rc){
    const ref=(def.referentials||[]).find(r=>String(codeOf(r.Referentiel_Code))===String(rc));
    const source=String(ref?.Type_source||"VALEURS_REFERENTIELS").trim().toUpperCase();
    if(source==="STRUCTURES"){
      for(const r of dashboardOrderedModalities(def.structures||[],true)){const k=String(codeOf(r.Structure_Code)||"");if(k)out.set(k,String(first(r,["Nom","Libelle","Libellé","Structure_Code"],k)));}
    }else{
      for(const r of dashboardOrderedModalities(def.referentialValues||[])){
        if(String(resolveRefCode(r.Referentiel_Code,def.referentials||[],"Referentiel_Code"))!==String(rc))continue;
        const k=String(codeOf(r.ValeurRef_Code)||"");
        if(k)out.set(k,String(first(r,["Libelle","Libellé","Valeur","ValeurRef_Code"],k)));
      }
    }
  }
  return out;
}
function dashboardNativeLabelOrder(q){return [...questionChoiceLabels(q).values()].map(v=>String(v))}
function dashboardSortRows(rows,mode="auto",nativeOrder=[],valueKey=""){
 const list=[...(rows||[])],m=String(mode||"auto");
 const byLabel=(a,b)=>String(a.label).localeCompare(String(b.label),"fr",{numeric:true});
 if(m==="auto"&&nativeOrder?.length){const pos=new Map(nativeOrder.map((v,i)=>[String(v),i]));return list.sort((a,b)=>{const ai=pos.has(String(a.label))?pos.get(String(a.label)):Number.MAX_SAFE_INTEGER,bi=pos.has(String(b.label))?pos.get(String(b.label)):Number.MAX_SAFE_INTEGER;return ai-bi||byLabel(a,b)})}
 if(m==="reverse")return list.reverse();
 if(m==="alpha_asc")return list.sort(byLabel);
 if(m==="alpha_desc")return list.sort((a,b)=>byLabel(b,a));
 if(m==="frequency_desc"||m==="frequency_asc")return list.sort((a,b)=>{const av=Number(a.__freq??a.n??a.count??0),bv=Number(b.__freq??b.n??b.count??0);return (m==="frequency_desc"?bv-av:av-bv)||byLabel(a,b)});
 if(m==="value_asc"||m==="value_desc"){
  const metric=(row)=>{if(valueKey){const v=Number(row[valueKey]);if(Number.isFinite(v))return v}
   for(const k of ["__value","sum","total","n","count","mean","median","min","max","distinct","withAny","__freq"]){const v=Number(row[k]);if(Number.isFinite(v))return v}
   return Number.NaN};
  return list.sort((a,b)=>{const av=metric(a),bv=metric(b),hasA=Number.isFinite(av),hasB=Number.isFinite(bv);if(hasA!==hasB)return hasA?-1:1;if(!hasA)return byLabel(a,b);const diff=m==="value_asc"?av-bv:bv-av;return diff||byLabel(a,b)})
 }
 return list
}
