function indicatorNumericBlock(vals,stats,title){const nums=vals.map(Number).filter(Number.isFinite).sort((a,b)=>a-b),parts=[];if(stats.has("count"))parts.push(["Valeurs renseignées",nums.length]);if(nums.length){if(stats.has("sum"))parts.push(["Somme",nums.reduce((a,b)=>a+b,0)]);if(stats.has("mean"))parts.push(["Moyenne",nums.reduce((a,b)=>a+b,0)/nums.length]);if(stats.has("median")){const m=Math.floor(nums.length/2);parts.push(["Médiane",nums.length%2?nums[m]:(nums[m-1]+nums[m])/2])}if(stats.has("min"))parts.push(["Minimum",nums[0]]);if(stats.has("max"))parts.push(["Maximum",nums[nums.length-1]])}return `<div class="indicator-card"><h4>${escapeHtml(title)}</h4>${indicatorKpis(parts)}</div>`}
function indicatorCategoricalBlock(src,vals,stats,chart,title){const labels=indicatorChoiceLabels(src),counts=new Map();for(const v of vals){const arr=Array.isArray(v)?v:[v];for(const z of arr){const k=String(codeOf(z)||z);counts.set(k,(counts.get(k)||0)+1)}}const items=dashboardSortRows([...counts].map(([k,n])=>({label:labels.get(k)||k,n})),"auto",[...labels.values()]),total=vals.length,showPercent=stats.has("percent");let graph="";if(chart==="pie")graph=indicatorPie(items,total);else if(chart==="bar")graph=indicatorBar(items,total,showPercent);const table=(stats.has("count")||showPercent)?`<div>${items.map(x=>`<div>${escapeHtml(x.label)}${stats.has("count")?` : <strong>${x.n}</strong>`:""}${showPercent&&total?` (${(100*x.n/total).toFixed(1)} %)` : ""}</div>`).join("")}</div>`:"";return `<div class="indicator-card"><h4>${escapeHtml(title)}</h4>${graph}${table}</div>`}
