 name=String(entered).trim();
 if(!name)return alert('Le nom ne peut pas être vide.');
 if(existingNames.has(name.toLocaleLowerCase('fr')))return alert('Ce nom est déjà utilisé. Choisissez un autre nom.');
 if(!confirm(`Dupliquer « ${source.Nom||'Dashboard'} » sous le nom « ${name} » ?\n\nLes onglets, indicateurs et regroupements seront copiés. Un nouveau lien sera généré. Les éventuelles modifications non enregistrées dans le formulaire ne seront pas copiées.`))return;
