 const values={Dashboard_Code:code,Nom:name,Campagne_Code:String(source.Campagne_Code||''),Jeton_acces:token,URL_dashboard:shareUrlForToken(token),Configuration_JSON:JSON.stringify(sourceConfig),Actif:true,Date_creation:Date.now()/1000};
 await grist.docApi.applyUserActions([["AddRecord","DASHBOARDS",null,values]]);
