function renderShare(row){const url=currentDashboardShareUrl(row);if(!row)return'<div class="share-card muted">Enregistrez d’abord le Dashboard pour obtenir son lien de partage.</div>';return `<div class="share-card"><div><strong>Partage</strong><div class="help">Lien de consultation du Dashboard</div></div><input id="share-url" readonly value="${escapeHtml(url||"Lien indisponible")}"><button type="button" id="copy-dashboard-link" ${url?"":"disabled"}>Copier le lien</button><button type="button" id="open-dashboard-preview" ${url?"":"disabled"}>Ouvrir la consultation</button></div>`}
const LAST_DASHBOARD_STORAGE_KEY="gristionnaire.dashboard.lastDashboardCode";
function rememberLastDashboard(row){try{const code=String(row?.Dashboard_Code||"").trim();if(code)localStorage.setItem(LAST_DASHBOARD_STORAGE_KEY,code)}catch(_){}}
function restoreLastDashboardSelection(){let code="";try{code=String(localStorage.getItem(LAST_DASHBOARD_STORAGE_KEY)||"").trim()}catch(_){}if(!code)return;const row=(state.loaded.DASHBOARDS||[]).filter(active).find(r=>String(r.Dashboard_Code||"").trim()===code);const sel=document.querySelector('#builder-dashboard');if(row&&sel){sel.value=String(row.id);sel.dispatchEvent(new Event('change'))}}
// La déclaration négative est définie explicitement par Dashboard, jamais déduite de l'absence de fiche.
function individualNoDeclarationQuestions(){
 const group=dashboardGroupRows(state.loaded?.CAMPAGNES||[]).find(g=>g.code===String(document.querySelector('#builder-campaign')?.value||''));
 const version=group?builderCampaignVersion(group):null;
 if(!version)return [];
 const vc=codeOf(version.Version_Code),versions=state.loaded?.VERSIONS_QUESTIONNAIRES||[],ficheTypes=state.loaded?.TYPES_FICHES||[];
 return (state.loaded?.QUESTIONS||[]).filter(q=>active(q)&&resolveRefCode(q.Version_Code,versions,'Version_Code')===vc&&!resolveRefCode(q.TypeFiche_Code,ficheTypes,'TypeFiche_Code')&&questionChoiceLabelsForBuilder(q).size);
}
function questionChoiceLabelsForBuilder(q){
 // Les listes et référentiels doivent être résolus dans le contexte de la campagne choisie.
 const group=dashboardGroupRows(state.loaded?.CAMPAGNES||[]).find(g=>g.code===String(document.querySelector('#builder-campaign')?.value||''));
 if(!group)return new Map();
 const def=state.definition, campaigns=state.campaigns;
 try{
  const version=builderCampaignVersion(group),vc=codeOf(version?.Version_Code),byVersion=rows=>(rows||[]).filter(r=>!('Version_Code' in r)||resolveRefCode(r.Version_Code,state.loaded?.VERSIONS_QUESTIONNAIRES||[],'Version_Code')===vc);
  state.definition={questions:byVersion(state.loaded?.QUESTIONS),choices:(state.loaded?.CHOIX_QUESTIONS||[]).filter(active),referentials:(state.loaded?.REFERENTIELS||[]).filter(active),referentialValues:(state.loaded?.VALEURS_REFERENTIELS||[]).filter(active),structures:(state.loaded?.STRUCTURES||[]).filter(active)};
  return questionChoiceLabels(q);
 }finally{state.definition=def;state.campaigns=campaigns;}
}
// Compatibilité avec les Dashboards V4.3.8 (une seule question) et les règles multiples.
function individualNoDeclarationRules(cfg={}){
 if(Array.isArray(cfg.individualNoDeclarationRules))return cfg.individualNoDeclarationRules.filter(r=>r&&r.question&&r.choice);
 const question=String(cfg.individualNoDeclarationQuestion||''),choice=String(cfg.individualNoDeclarationChoice||'');
 return question&&choice?[{question,choice}]:[];
}
function refreshIndividualNoDeclarationConfig(cfg={}){
 const host=document.querySelector('#builder-no-declaration-rules'),filter=document.querySelector('#builder-individual-default-filter');if(!host)return;
 const questions=individualNoDeclarationQuestions(),rules=individualNoDeclarationRules(cfg);
 host.innerHTML='';
 const add=(rule={})=>{
  const row=document.createElement('div');row.setAttribute('data-no-declaration-rule','');row.style.cssText='display:grid;grid-template-columns:minmax(160px,1fr) minmax(160px,1fr) auto;gap:10px;align-items:end;margin:8px 0';
  row.innerHTML=`<label>Question<select data-no-declaration-question><option value="">— Choisir une question —</option>${questions.map(q=>`<option value="${escapeHtml(codeOf(q.Question_Code))}">${escapeHtml(questionLabel(q))} (${escapeHtml(codeOf(q.Question_Code))})</option>`).join('')}</select></label><label>Modalité « Rien à déclarer »<select data-no-declaration-choice><option value="">— Choisir une modalité —</option></select></label><button type="button" data-remove-no-declaration-rule title="Retirer cette règle">Retirer</button>`;
  host.appendChild(row);
  const qselect=row.querySelector('[data-no-declaration-question]'),cselect=row.querySelector('[data-no-declaration-choice]');
  const syncChoice=(choiceValue='')=>{
   const q=questions.find(q=>codeOf(q.Question_Code)===qselect.value),choices=q?questionChoiceLabelsForBuilder(q):new Map();
   cselect.innerHTML=`<option value="">— Choisir une modalité —</option>`+[...choices].map(([code,label])=>`<option value="${escapeHtml(code)}">${escapeHtml(label)}</option>`).join('');
   cselect.value=choices.has(choiceValue)?choiceValue:'';cselect.disabled=!q;
  };
  qselect.value=questions.some(q=>codeOf(q.Question_Code)===String(rule.question||''))?String(rule.question):'';
  syncChoice(String(rule.choice||''));qselect.onchange=()=>syncChoice();
  row.querySelector('[data-remove-no-declaration-rule]').onclick=()=>row.remove();
 };
 rules.forEach(add);
 document.querySelector('#builder-add-no-declaration-rule').onclick=()=>add();
 if(filter)filter.value=['all','with','declared','other'].includes(cfg.individualDefaultFilter)?cfg.individualDefaultFilter:'all';
 const ficheLabelInput=document.querySelector('#builder-individual-fiche-label');if(ficheLabelInput)ficheLabelInput.value=String(cfg.individualFicheLabel||'');
}

function builderPeriodOptions(group){
 const questionnaire=questionnaireKeyFromCampaign(group?.first),rows=state.loaded?.QUESTIONNAIRES||[];
 if(!questionnaire)return[];
 return (state.loaded?.PERIODES_QUESTIONNAIRE||[]).filter(p=>resolveRefCode(p.Questionnaire_Code,rows,'Questionnaire_Code')===questionnaire).sort((a,b)=>String(a.Date_debut||a.Libelle||'').localeCompare(String(b.Date_debut||b.Libelle||''),'fr'));
}
function refreshBuilderPeriodConfig(cfg={}){
 const host=document.querySelector('#builder-period-fields'),panel=document.querySelector('#builder-period-panel');if(!host)return;
 const periods=builderPeriodOptions(builderCurrentGroup());panel.hidden=periods.length===0;
 if(!periods.length){host.innerHTML='';return}
 const selection=cfg.periodSelectionEnabled!==false,comparison=cfg.periodComparisonEnabled!==false;
 const mode=cfg.periodDefaultMode==='specific'?'specific':'latest',current=String(cfg.periodDefaultCode||'');
 host.innerHTML=`<div class="dashboard-period-settings"><label class="dashboard-period-check"><input type="checkbox" id="builder-period-selection" ${selection?'checked':''}> Autoriser le choix de la période dans la consultation</label><div class="dashboard-period-default-grid"><label>À l’ouverture du Dashboard<select id="builder-period-default-mode"><option value="latest" ${mode==='latest'?'selected':''}>Dernière période disponible (automatique)</option><option value="specific" ${mode==='specific'?'selected':''}>Période définie par l’administrateur</option></select></label><label data-period-specific>Période choisie<select id="builder-period-default-code">${periods.map(p=>`<option value="${escapeHtml(codeOf(p.Periode_Code))}" ${current===codeOf(p.Periode_Code)?'selected':''}>${escapeHtml(p.Libelle||codeOf(p.Periode_Code))}</option>`).join('')}</select></label></div><label class="dashboard-period-check"><input type="checkbox" id="builder-period-comparison" ${comparison?'checked':''}> Autoriser la comparaison de plusieurs périodes</label><p class="help">À l’ouverture, les indicateurs de la période par défaut sont affichés. La comparaison ne s’active que sur demande.</p></div>`;
 const modeField=host.querySelector('#builder-period-default-mode'),specific=host.querySelector('[data-period-specific]');const sync=()=>specific.hidden=modeField.value!=='specific';modeField.addEventListener('change',sync);sync();
}
function renderBuilder(){const root=document.querySelector('#root'),groups=dashboardGroupRows(state.loaded.CAMPAGNES||[]),rows=(state.loaded.DASHBOARDS||[]).filter(active);root.innerHTML=`<div class="builder-shell"><div class="dash-head builder-page-head"><div><h1>Constructeur de Dashboard</h1><div class="muted">Configurez le tableau de bord, préparez vos regroupements puis construisez les onglets de restitution.</div></div><div class="builder-main-actions"><button type="button" id="delete-dashboard" class="danger" disabled>Supprimer</button><button type="button" id="reassign-dashboard-campaign" disabled>Réaffecter la campagne</button><button type="button" id="duplicate-dashboard" disabled>Dupliquer</button><button type="button" id="preview-dashboard">Aperçu</button><button type="button" class="primary" id="save-dashboard">Enregistrer</button></div></div><section class="builder-section builder-config-section"><div class="builder-section-heading"><span class="builder-step">1</span><div><h2>Configuration</h2><div class="help">Choisissez le Dashboard et la campagne auxquels vous souhaitez travailler.</div></div></div><div class="builder-toolbar builder-config-grid"><label>Dashboard<select id="builder-dashboard"><option value="new">+ Nouveau Dashboard</option>${rows.map(r=>`<option value="${r.id}">${escapeHtml(r.Nom||r.Dashboard_Code||`Dashboard ${r.id}`)}</option>`).join("")}</select></label><label>Nom du Dashboard<input id="builder-name" placeholder="Ex. Tableau de bord FDP"></label><label>Campagne<select id="builder-campaign"><option value="">— Sélectionner —</option>${groups.map(g=>`<option value="${escapeHtml(g.code)}">${escapeHtml(g.name)}</option>`).join("")}</select></label></div><label class="check" style="display:flex;align-items:center;gap:8px;margin-top:12px"><input type="checkbox" id="builder-individual-responses"> Ajouter un onglet « Réponses individuelles » (consultation uniquement)</label><div class="help">Cet onglet présente les réponses par répondant, y compris les fiches. Il est propre à ce Dashboard et ne donne pas de droit de modification.</div><details class="builder-panel" style="margin-top:14px"><summary><span><strong>Classement des réponses individuelles</strong><small>Questions « Rien à déclarer », libellé des fiches et affichage par défaut</small></span><span class="dashboard-disclosure">▾</span></summary><div class="builder-panel-body"><div class="help">Optionnel : associez une ou plusieurs questions à leurs modalités « Rien à déclarer ». Une seule règle vérifiée suffit pour classer la réponse dans cette catégorie (OU).</div><div id="builder-no-declaration-rules" style="margin-top:10px"></div><button type="button" id="builder-add-no-declaration-rule" style="margin:6px 0 10px">+ Ajouter une question</button><div class="builder-config-grid"><label>Libellé des fiches dans la consultation<input type="text" id="builder-individual-fiche-label" placeholder="Fiche (par défaut)" maxlength="80"></label><label>Catégorie affichée par défaut<select id="builder-individual-default-filter"><option value="all">Toutes les réponses</option><option value="with">Avec fiches</option><option value="declared">Rien à déclarer</option><option value="other">Autres réponses</option></select></label></div></div></details><details class="builder-panel dashboard-period-builder" id="builder-period-panel" style="margin-top:14px"><summary><span><strong>Gestion des périodes</strong><small>Période par défaut et comparaison facultative</small></span><span class="dashboard-disclosure">▾</span></summary><div class="builder-panel-body"><div id="builder-period-fields"></div></div></details></section><div class="builder-secondary-grid"><details class="builder-panel"><summary><span><strong>Partage</strong><small>Lien de consultation du Dashboard</small></span><span class="dashboard-disclosure">▾</span></summary><div class="builder-panel-body" id="builder-share">${renderShare(null)}</div></details><details class="builder-panel"><summary><span><strong>Regroupements</strong><small>Préparez les ventilations personnalisées</small></span><span class="dashboard-disclosure">▾</span></summary><div class="builder-panel-body" id="builder-groupings"></div></details></div><section class="builder-section builder-design-section"><div class="builder-section-heading builder-design-heading"><span class="builder-step">2</span><div><h2>Conception du Dashboard</h2><div class="help">Organisez votre restitution en onglets puis ajoutez les indicateurs et contenus nécessaires.</div></div><button type="button" id="add-dashboard-tab">+ Ajouter un onglet</button></div><div id="builder-tabs"></div></section><div id="builder-preview" class="builder-preview" hidden></div></div>`;bindBuilder()}

function normalizeDashboardGroupings(config={}){return Array.isArray(config.groupings)?config.groupings.map((g,i)=>({id:g.id||uid('GRP'),name:g.name||`Regroupement ${i+1}`,source:g.source||"",fallbackSource:g.fallbackSource||"",groups:Array.isArray(g.groups)?g.groups.map((x,j)=>({id:x.id||uid('VAL'),label:x.label||`Groupe ${j+1}`,values:Array.isArray(x.values)?x.values.map(String):[]})):[]})):[]}
function groupingSourceOptions(group){return sourceOptions(group).filter(x=>x.kind==="q"||x.kind==="fq")}
function builderQuestionChoiceLabels(group,q){const out=new Map(),questions=versionQuestions(group),qc=String(codeOf(q?.Question_Code)||"");for(const c of dashboardOrderedModalities(state.loaded.CHOIX_QUESTIONS||[])){if(!active(c))continue;if(String(resolveRefCode(c.Question_Code,questions,"Question_Code"))!==qc)continue;const k=String(codeOf(c.Choix_Code)||"");if(k)out.set(k,String(first(c,["Libelle","Libellé","Valeur","Choix_Code"],k)))}const allRefs=state.loaded.REFERENTIELS||[],rc=resolveRefCode(q?.Referentiel_Code,allRefs,"Referentiel_Code");if(rc){const rawRef=codeOf(q?.Referentiel_Code),ref=allRefs.find(r=>String(r.id)===String(rawRef)||String(codeOf(r.Referentiel_Code))===String(rc)),source=String(ref?.Type_source||"VALEURS_REFERENTIELS").trim().toUpperCase();if(source==="STRUCTURES"){for(const r of dashboardOrderedModalities((state.loaded.STRUCTURES||[]).filter(active),true)){const k=String(codeOf(r.Structure_Code)||"");if(k)out.set(k,String(first(r,["Nom","Libelle","Libellé","Structure_Code"],k)))}}else{for(const r of dashboardOrderedModalities((state.loaded.VALEURS_REFERENTIELS||[]).filter(active))){if(String(resolveRefCode(r.Referentiel_Code,allRefs,"Referentiel_Code"))!==String(rc))continue;const k=String(codeOf(r.ValeurRef_Code)||"");if(k)out.set(k,String(first(r,["Libelle","Libellé","Valeur","ValeurRef_Code"],k)))}}}return out}
function groupingSourceValues(group,sourceToken){const src=sourceByToken(group,sourceToken);if(!src?.q)return[];const labels=builderQuestionChoiceLabels(group,src.q),values=new Map(labels);/* La définition de la question est la source principale : choix, référentiel ou STRUCTURES. */if(!values.size){try{for(const item of valuesForSource(src))for(const raw of nonEmptyGroups(item.value)){const key=String(codeOf(raw)||raw);if(key&&!values.has(key))values.set(key,key)}}catch(_){}}return [...values].map(([value,label])=>({value,label}))}
function groupingEditorGroupHtml(g,sourceValues){const selected=new Set((g.values||[]).map(String)),known=new Set((sourceValues||[]).map(x=>String(x.value))),allValues=[...(sourceValues||[]),...[...selected].filter(v=>!known.has(v)).map(v=>({value:v,label:v}))],label=String(g.label||"Nouveau groupe"),count=selected.size;return `<details class="dashboard-group-row" data-grouping-group data-group-id="${escapeHtml(g.id||uid('VAL'))}"><summary><span><strong data-group-summary-label>${escapeHtml(label)}</strong><small>${count} valeur${count>1?"s":""}</small></span><span class="dashboard-disclosure">▾</span></summary><div class="dashboard-group-row-body"><label>Nom du groupe<input data-group-label value="${escapeHtml(g.label||"")}"></label><div class="dashboard-group-values"><label>Valeurs / structures à regrouper<input type="search" data-group-values-search placeholder="Rechercher une valeur…"></label><div class="dashboard-group-values-list" data-group-values-list>${allValues.map(x=>`<label class="dashboard-group-value" data-group-value-label="${escapeHtml(String(x.label).toLowerCase())}"><input type="checkbox" data-group-value value="${escapeHtml(x.value)}" ${selected.has(String(x.value))?"checked":""}><span>${escapeHtml(x.label)}</span></label>`).join("")}</div></div><div class="dashboard-group-order-actions"><button type="button" data-group-up>↑ Monter</button><button type="button" data-group-down>↓ Descendre</button><button type="button" data-remove-group>Supprimer ce groupe</button></div></div></details>`}
function groupingEditorHtml(g,group){const sources=groupingSourceOptions(group),vals=groupingSourceValues(group,g.source),src=sourceByToken(group,g.source),fallbacks=sourceOptions(group).filter(x=>x.kind==="q"),name=String(g.name||"Nouveau regroupement"),sourceLabel=src?.label||"Variable non sélectionnée",n=(g.groups||[]).length;return `<details class="dashboard-grouping-card" data-dashboard-grouping data-grouping-id="${escapeHtml(g.id||uid('GRP'))}"><summary class="dashboard-grouping-summary"><span><strong data-grouping-summary-name>${escapeHtml(name)}</strong><small>${escapeHtml(sourceLabel)} · ${n} groupe${n>1?"s":""}</small></span><span class="dashboard-disclosure">▾</span></summary><div class="dashboard-grouping-body"><div class="builder-block-head"><strong>Paramètres du regroupement</strong><div><button type="button" data-duplicate-grouping>Dupliquer</button><button type="button" data-remove-grouping>Supprimer le regroupement</button></div></div><div class="builder-indicator-grid"><label>Nom du regroupement<input data-grouping-name placeholder="Ex. Services" value="${escapeHtml(g.name||"")}"></label><label>Variable à regrouper<select data-grouping-source>${optionHtml(sources,g.source)}</select></label>${src?.kind==="fq"?`<label>Valeur de repli si la fiche est vide<select data-grouping-fallback><option value="">— Aucun repli —</option>${fallbacks.map(x=>`<option value="${escapeHtml(x.token)}" ${String(g.fallbackSource||"")===String(x.token)?"selected":""}>${escapeHtml(x.label)}</option>`).join("")}</select></label>`:""}</div><div class="help">Créez vos groupes puis sélectionnez les valeurs qui doivent être consolidées ensemble.</div><div data-grouping-groups>${(g.groups||[]).map(x=>groupingEditorGroupHtml(x,vals)).join("")}</div><button type="button" data-add-group>+ Ajouter un groupe</button></div></details>`}
function groupingFromElement(el){return{id:el.dataset.groupingId||uid('GRP'),name:el.querySelector('[data-grouping-name]')?.value||"",source:el.querySelector('[data-grouping-source]')?.value||"",fallbackSource:el.querySelector('[data-grouping-fallback]')?.value||"",groups:[...el.querySelectorAll('[data-grouping-group]')].map(x=>({id:x.dataset.groupId||uid('VAL'),label:x.querySelector('[data-group-label]')?.value||"",values:[...x.querySelectorAll('[data-group-value]:checked')].map(o=>o.value)}))}}
function builderGroupingsFromForm(){return[...document.querySelectorAll('[data-dashboard-grouping]')].map(groupingFromElement)}
function cloneDashboardGrouping(g,nameSuffix=""){return{id:uid('GRP'),name:`${g?.name||'Regroupement'}${nameSuffix}`,source:g?.source||"",fallbackSource:g?.fallbackSource||"",groups:(g?.groups||[]).map(x=>({id:uid('VAL'),label:x.label||"",values:Array.isArray(x.values)?x.values.map(String):[]}))}}
function dashboardGroupingLibrary(){const out=[];for(const row of(state.loaded.DASHBOARDS||[]).filter(active)){const cfg=dashboardConfig(row);for(const g of normalizeDashboardGroupings(cfg)){if(!g.groups?.length)continue;out.push({key:`dashboard:${row.id}:${g.id}`,origin:"dashboard",label:row.Nom||row.Dashboard_Code||`Dashboard ${row.id}`,grouping:g})}}return out}
function savedGroupingLibrary(){const out=[];for(const row of(state.loaded.BIBLIOTHEQUE_REGROUPEMENTS||[]).filter(active)){let cfg={};try{cfg=JSON.parse(row.Configuration_JSON||"{}")||{}}catch{continue}const normalized=normalizeDashboardGroupings({groupings:[{...cfg,name:cfg.name||row.Nom||"Regroupement",source:cfg.source||row.Source||""}]})[0];if(!normalized?.groups?.length)continue;out.push({key:`library:${row.id}`,origin:"library",label:row.Nom||normalized.name||`Regroupement ${row.id}`,grouping:normalized})}return out}
function groupingLibraryItems(){return[...savedGroupingLibrary(),...dashboardGroupingLibrary()]}
function groupingLibraryOptions(){const lib=savedGroupingLibrary(),dash=dashboardGroupingLibrary();return`${lib.length?`<optgroup label="Bibliothèque">${lib.map(x=>`<option value="${escapeHtml(x.key)}">${escapeHtml(x.label)}</option>`).join("")}</optgroup>`:""}${dash.length?`<optgroup label="Autres Dashboards">${dash.map(x=>`<option value="${escapeHtml(x.key)}">${escapeHtml(x.label)} — ${escapeHtml(x.grouping.name||"Sans nom")}</option>`).join("")}</optgroup>`:""}`}
function importDashboardGrouping(key){const item=groupingLibraryItems().find(x=>x.key===key);if(!item)return null;return cloneDashboardGrouping(item.grouping,item.origin==="library"?"":" (copie)")}
