function renderIndividualDetailContent(index){
 const h=state.hydrated[index];if(!h)return '';
 const cfg=dashboardConfig(state.dashboard),noun=String(cfg.individualFicheLabel||'').trim()||'Fiche';
 const plural=n=>noun+(n>1?'s':'');
 const allQuestions=state.definition?.questions||[],ficheTypes=state.definition?.ficheTypes||[];
 const main=allQuestions.filter(q=>active(q)&&!resolveRefCode(q.TypeFiche_Code,ficheTypes,'TypeFiche_Code')&&!['description','sommaire','indicateurs','tableau_donnees'].includes(String(first(q,['Type_question','Type'],'')).toLowerCase()));
 const answerRows=(answers,questions)=>questions.map(q=>`<div class="answer-row"><strong>${escapeHtml(questionLabel(q))}</strong>${escapeHtml(scalarDisplay(answers?.[codeOf(q.Question_Code)],q))}</div>`).join('');
 // Questionnaire classique : aucune navigation de fiches, les réponses s'affichent directement.
 // Se baser sur la définition du questionnaire, et non sur le nombre de fiches du répondant :
 // un répondant sans fiche dans une enquête à fiches doit conserver l'interface existante.
 if(!ficheTypes.length){
  return `<h2>${escapeHtml(responseLabel(h,index))}</h2><section class="dash-card"><h3>Réponses du questionnaire</h3>${main.length?answerRows(h.principalAnswers,main):'<div class="help">Aucune question à afficher.</div>'}</section>`;
 }
 const fiches=[];
 for(const ft of ficheTypes){const fc=codeOf(ft.TypeFiche_Code),rows=(h.fiches?.[fc]||[]).filter(f=>!state.periodCode||!f.periodeCode||String(f.periodeCode)===String(state.periodCode)),questions=allQuestions.filter(q=>resolveRefCode(q.TypeFiche_Code,ficheTypes,'TypeFiche_Code')===fc);rows.forEach((f,i)=>{const title=String(f.title||f.titre||f.Nom||f.Libelle||'').trim()||`${ficheLabel(ft)} ${i+1}`;fiches.push({title:`${ficheLabel(ft)} — ${title}`,html:answerRows(f.answers,questions)})})}
 const panels=fiches.map((f,i)=>`<section data-individual-fiche-panel="${i}" ${i===0?'':'hidden'}><h3 style="margin-top:12px">${escapeHtml(f.title)}</h3>${f.html||'<div class="help">Aucune question dans cette fiche.</div>'}</section>`).join('');
 // Des rangées séparées maintiennent les commandes parfaitement alignées, même en petite largeur.
 const summary=`<div style="display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px;margin:12px 0"><button type="button" data-individual-main-toggle>Afficher les réponses générales</button><span class="help" style="margin:0">${fiches.length} ${escapeHtml(plural(fiches.length).toLocaleLowerCase('fr-FR'))} au total</span></div>`;
 const navigation=fiches.length?`<div class="dash-card"><div style="display:grid;grid-template-columns:minmax(0,1fr) auto auto;align-items:end;gap:10px"><label style="display:block;min-width:0;margin:0">Choisir ${escapeHtml(noun==='Fiche'?'une fiche':'un '+noun.toLocaleLowerCase('fr-FR'))}<select data-individual-fiche-select style="display:block;width:100%;margin-top:5px">${fiches.map((f,i)=>`<option value="${i}">${escapeHtml(`${i+1}. ${f.title}`)}</option>`).join('')}</select></label><button type="button" data-individual-prev style="align-self:end;margin:0;white-space:nowrap" disabled>← Précédente</button><button type="button" data-individual-next style="align-self:end;margin:0;white-space:nowrap" ${fiches.length===1?'disabled':''}>Suivante →</button></div><div class="help" data-individual-position>${escapeHtml(noun)} 1 sur ${fiches.length}</div>${panels}</div>`:`<div class="dash-card"><p>Aucun ${escapeHtml(noun.toLocaleLowerCase('fr-FR'))} enregistré pour ce répondant.</p></div>`;
 return `<h2>${escapeHtml(responseLabel(h,index))}</h2>${summary}<section data-individual-main hidden class="dash-card"><h3>Réponses générales</h3>${answerRows(h.principalAnswers,main)}</section>${navigation}`;
}
// Impression individuelle : un répondant par document, toutes ses fiches visibles.
// On réutilise la présentation des réponses déjà affichée par la consultation,
// sans modifier les données ni générer un fichier contenant d'autres répondants.
function printIndividualResponse(index){
 if(!Number.isInteger(index)||index<0||index>=state.hydrated.length)return;
 document.querySelector('#dashboard-individual-print-sheet')?.remove();
 const sheet=document.createElement('section');
 sheet.id='dashboard-individual-print-sheet';
 sheet.setAttribute('aria-label','Export PDF des réponses individuelles');
 const period=state.periodCode?(state.periods||[]).find(p=>String(codeOf(p.Periode_Code))===String(state.periodCode)):null;
 const periodTitle=period?String(period.Libelle||period.Nom||state.periodCode):'';
 sheet.innerHTML=`<header class="individual-print-header"><h1>${escapeHtml(state.dashboard?.Nom||'Tableau de bord')}</h1><p>${escapeHtml(state.campaigns?.[0]?.Nom||'')}${periodTitle?' — '+escapeHtml(periodTitle):''}</p></header>${renderIndividualDetailContent(index)}`;
 // L'interface interactive affiche une fiche à la fois ; un PDF doit les inclure toutes.
 sheet.querySelectorAll('[data-individual-main],[data-individual-fiche-panel]').forEach(panel=>{panel.hidden=false;panel.removeAttribute('hidden')});
 sheet.querySelectorAll('button,select,[data-individual-position],[data-individual-main-toggle]').forEach(node=>node.remove());
 sheet.querySelectorAll('label').forEach(label=>{if(label.querySelector('select')||!label.textContent.trim())label.remove()});
 // Éviter le compteur d'interface et les sélecteurs vides dans l'impression.
 sheet.querySelectorAll('[data-individual-fiche-select]').forEach(node=>node.remove());
 document.body.appendChild(sheet);
 document.body.classList.remove('dashboard-print-all');
 document.body.classList.add('dashboard-print-individual');
 let cleaned=false;
 const cleanup=()=>{if(cleaned)return;cleaned=true;document.body.classList.remove('dashboard-print-individual');sheet.remove();window.removeEventListener('afterprint',cleanup)};
 window.addEventListener('afterprint',cleanup);
 try{window.print()}catch(err){cleanup();throw err}
}
// V4.3.22 — Exports groupés : aucun appel serveur, les PDF sont créés localement.
// Le périmètre « affichés » reprend exactement la recherche et la catégorie actives.
function individualExportIndices(host){
 const scope=host.querySelector('[data-individual-export-scope]')?.value||'visible';
 if(scope==='all')return state.hydrated.map((_,i)=>i);
 return [...host.querySelectorAll('[data-individual-row]')].filter(row=>!row.hidden).map(row=>Number(row.querySelector('[data-individual-response]')?.dataset.individualResponse)).filter(i=>Number.isInteger(i)&&i>=0&&i<state.hydrated.length);
}
function individualExportDocument(index){
 const el=document.createElement('div');el.innerHTML=renderIndividualDetailContent(index);
 el.querySelectorAll('[data-individual-main],[data-individual-fiche-panel]').forEach(panel=>{panel.hidden=false;panel.removeAttribute('hidden')});
 el.querySelectorAll('button,select,[data-individual-position]').forEach(n=>n.remove());
 const lines=[];
 const clean=s=>String(s||'').replace(/\s+/g,' ').trim();
 const title=clean(el.querySelector('h2')?.textContent)||responseLabel(state.hydrated[index],index);
 lines.push({text:title,kind:'respondent'});
 for(const node of el.querySelectorAll('h3,.answer-row')){
  if(node.classList.contains('answer-row')){
   const label=clean(node.querySelector('strong')?.textContent);
   const value=clean(node.textContent.slice((node.querySelector('strong')?.textContent||'').length));
   lines.push({text:label+(value?' : '+value:' : —'),kind:'answer'});
  }else lines.push({text:clean(node.textContent),kind:'heading'});
 }
 return {title,lines};
}
function individualExportHeader(){
 const period=state.periodCode?(state.periods||[]).find(p=>String(codeOf(p.Periode_Code))===String(state.periodCode)):null;
 return [String(state.dashboard?.Nom||'Tableau de bord'),String(state.campaigns?.[0]?.Nom||''),period?String(period.Libelle||period.Nom||state.periodCode):''].filter(Boolean);
}
// PDF texte paginé, autonome (A4, police PDF standard). Pas de service tiers ni de dépendance réseau.
function createIndividualPdf(documents){
 const cp1252={'€':128,'‚':130,'ƒ':131,'„':132,'…':133,'†':134,'‡':135,'ˆ':136,'‰':137,'Š':138,'‹':139,'Œ':140,'Ž':142,'‘':145,'’':146,'“':147,'”':148,'•':149,'–':150,'—':151,'˜':152,'™':153,'š':154,'›':155,'œ':156,'ž':158,'Ÿ':159};
 const latin=s=>{let out='';for(const c of String(s)){const n=c.codePointAt(0);out+=String.fromCharCode(n<=255?n:(cp1252[c]||63))}return out};
 const pdfText=s=>latin(s).replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)').replace(/[\r\n]/g,' ');
 const pages=[];let ops=[],y=795;
 const start=()=>{ops=[];y=795};
 const finish=()=>{if(ops.length)pages.push(ops.join('\n'));start()};
 const line=(str,size=10,bold=false,indent=0)=>{if(y<54)finish();ops.push(`BT /${bold?'F2':'F1'} ${size} Tf 1 0 0 1 ${44+indent} ${y} Tm (${pdfText(str)}) Tj ET`);y-=size+5};
 const wrap=(txt,max)=>{const words=String(txt).split(/\s+/),result=[];let current='';for(const w of words){if(!w)continue;if(w.length>max){if(current){result.push(current);current=''}for(let j=0;j<w.length;j+=max)result.push(w.slice(j,j+max));continue}if((current+' '+w).trim().length>max){result.push(current);current=w}else current=(current+' '+w).trim()}if(current)result.push(current);return result.length?result:['']};
 start();
 for(let i=0;i<documents.length;i++){
  if(i)finish();
  individualExportHeader().forEach((s,j)=>wrap(s,j===0?65:90).forEach(w=>line(w,j===0?16:10,j===0)));
  y-=12;
  for(const item of documents[i].lines){if(item.kind==='heading'||item.kind==='respondent')y-=6;for(const w of wrap(item.text,item.kind==='answer'?100:85))line(w,item.kind==='respondent'?14:item.kind==='heading'?12:10,item.kind!=='answer',item.kind==='answer'?6:0)}
 }
 finish();
 const objects=['','<< /Type /Catalog /Pages 2 0 R >>','', '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>','<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>'];
 const kids=[];
 for(const content of pages){const pageId=objects.length,streamId=pageId+1;kids.push(`${pageId} 0 R`);objects.push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> /Contents ${streamId} 0 R >>`);objects.push(`<< /Length ${content.length} >>\nstream\n${content}\nendstream`)}
 objects[2]=`<< /Type /Pages /Kids [${kids.join(' ')}] /Count ${kids.length} >>`;
 let output='%PDF-1.4\n%\xE2\xE3\xCF\xD3\n',offsets=[0];
 for(let i=1;i<objects.length;i++){offsets.push(output.length);output+=`${i} 0 obj\n${objects[i]}\nendobj\n`}
 const xref=output.length;output+=`xref\n0 ${objects.length}\n0000000000 65535 f \n`;
 for(let i=1;i<offsets.length;i++)output+=`${String(offsets[i]).padStart(10,'0')} 00000 n \n`;
 output+=`trailer\n<< /Size ${objects.length} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF`;
 return new Blob([Uint8Array.from(output,c=>c.charCodeAt(0))],{type:'application/pdf'});
}
function safeExportName(s){return String(s||'repondant').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'_').replace(/^_+|_+$/g,'').slice(0,70)||'repondant'}
function downloadIndividualBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
async function exportIndividualResponses(button,format){
 const host=button.closest('.dash-card');if(!host)return;
 const message=host.querySelector('[data-individual-export-status]'),indices=individualExportIndices(host);
 if(!indices.length){if(message)message.textContent='Aucun répondant dans ce périmètre.';return}
 const buttons=[...host.querySelectorAll('[data-individual-export-pdf],[data-individual-export-zip]')];buttons.forEach(b=>b.disabled=true);
 if(message)message.textContent=`Préparation de ${indices.length} répondant(s)…`;
 try{
  const documents=indices.map(individualExportDocument),base=safeExportName(state.dashboard?.Nom||'Dashboard');
  if(format==='pdf')downloadIndividualBlob(createIndividualPdf(documents),`${base}_reponses.pdf`);
  else{
   if(typeof JSZip==='undefined')throw new Error('La bibliothèque ZIP locale est indisponible.');
   const zip=new JSZip(),used=new Set();
   for(let i=0;i<documents.length;i++){
    const baseName=safeExportName(documents[i].title),id=indices[i],name=`${baseName}_${id+1}.pdf`;
    if(used.has(name))throw new Error('Nom de fichier en double.');used.add(name);
    zip.file(name,await createIndividualPdf([documents[i]]).arrayBuffer());
   }
   const blob=await zip.generateAsync({type:'blob',compression:'DEFLATE'});
   downloadIndividualBlob(blob,`${base}_reponses_individuelles.zip`);
  }
  if(message)message.textContent=`Export préparé : ${indices.length} répondant(s).`;
 }catch(err){if(message)message.textContent=`Export impossible : ${err?.message||err}`;}
 finally{buttons.forEach(b=>b.disabled=false)}
}
function showIndividualResponseDetail(index){
 if(!Number.isInteger(index)||index<0||index>=state.hydrated.length)return;
 const existing=document.querySelector('#individual-response-dialog');if(existing)existing.remove();
 const cover=document.createElement('div');cover.id='individual-response-dialog';cover.setAttribute('role','dialog');cover.setAttribute('aria-modal','true');cover.setAttribute('aria-label','Détail des réponses individuelles');
 cover.style.cssText='position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:9999;display:flex;justify-content:center;align-items:center;padding:18px';
 cover.innerHTML=`<div style="background:var(--background,#fff);color:var(--text-color,#222);width:min(100%,1050px);max-height:92vh;overflow:auto;border-radius:10px;padding:20px"><div style="display:flex;justify-content:flex-end;position:sticky;top:0;z-index:1;background:var(--background,#fff)"><button type="button" data-close-individual>Fermer ✕</button></div>${renderIndividualDetailContent(index)}</div>`;
 cover.querySelector('[data-close-individual]').onclick=()=>cover.remove();cover.addEventListener('click',e=>{if(e.target===cover)cover.remove()});
 cover.querySelector('[data-individual-main-toggle]')?.addEventListener('click',e=>{const panel=cover.querySelector('[data-individual-main]');panel.hidden=!panel.hidden;e.currentTarget.textContent=panel.hidden?'Afficher les réponses générales':'Masquer les réponses générales'});
 const select=cover.querySelector('[data-individual-fiche-select]'),panels=[...cover.querySelectorAll('[data-individual-fiche-panel]')];
 if(select){const change=(index)=>{const i=Math.min(Math.max(index,0),panels.length-1);select.value=String(i);panels.forEach((p,n)=>p.hidden=n!==i);cover.querySelector('[data-individual-prev]').disabled=i===0;cover.querySelector('[data-individual-next]').disabled=i===panels.length-1;cover.querySelector('[data-individual-position]').textContent=`${String(dashboardConfig(state.dashboard).individualFicheLabel||'').trim()||'Fiche'} ${i+1} sur ${panels.length}`};select.addEventListener('change',()=>change(Number(select.value)));cover.querySelector('[data-individual-prev]').onclick=()=>change(Number(select.value)-1);cover.querySelector('[data-individual-next]').onclick=()=>change(Number(select.value)+1)}
 document.body.appendChild(cover);
}

function bindDashboardViewTabs(root=document){root.querySelectorAll('[data-view-tab]').forEach(btn=>btn.onclick=()=>{const host=btn.closest('.dashboard-tabs');host.querySelectorAll('[data-view-tab]').forEach(x=>x.classList.toggle('is-active',x===btn));host.querySelectorAll('[data-view-tab-panel]').forEach(p=>{const active=p.dataset.viewTabPanel===btn.dataset.viewTab;p.hidden=!active;p.classList.toggle('is-active',active)})})}
async function previewBuilderDashboard(){const groupCode=document.querySelector('#builder-campaign')?.value||"";if(!groupCode)throw new Error('Sélectionnez une campagne.');const group=prepareCampaignData(groupCode),cfg=builderConfigFromForm(),host=document.querySelector('#builder-preview');host.hidden=false;host.innerHTML=`<div class="preview-head"><div><strong>Aperçu du tableau de bord</strong><div class="muted">${escapeHtml(responseScopeLabel())}</div>${responseScopeControl()}</div><button type="button" id="close-preview">Fermer l’aperçu</button></div>${renderBlocksFromConfig(cfg,group)}`;bindDashboardViewTabs(host);bindResponseScope();document.querySelector('#close-preview').onclick=()=>host.hidden=true;host.scrollIntoView({behavior:'smooth',block:'start'})}
async function saveBuilderDashboard(){const sel=document.querySelector('#builder-dashboard'),name=String(document.querySelector('#builder-name').value||"").trim(),group=String(document.querySelector('#builder-campaign').value||"").trim();if(!name){alert('Saisissez un nom de Dashboard.');return}if(!group){alert('Sélectionnez une campagne.');return}const cfg=builderConfigFromForm(),existing=sel.value!=="new"?builderRow(sel.value):null;let token=String(existing?.Jeton_acces||existing?.Jeton_dashboard||"").trim()||`Dashboard_${uid('ACCES').replace(/^ACCES_/,"")}`,url=shareUrlForToken(token)||String(existing?.URL_dashboard||"").trim();if(existing){const values={Nom:name,Campagne_Code:group,Jeton_acces:token,URL_dashboard:url,Configuration_JSON:JSON.stringify(cfg),Actif:true};await grist.docApi.applyUserActions([["UpdateRecord","DASHBOARDS",existing.id,values]])}else{const values={Dashboard_Code:uid('DASH'),Nom:name,Campagne_Code:group,Jeton_acces:token,URL_dashboard:url,Configuration_JSON:JSON.stringify(cfg),Actif:true,Date_creation:Date.now()/1000};await grist.docApi.applyUserActions([["AddRecord","DASHBOARDS",null,values]])}await reloadDashboardRows();renderBuilder();const match=(state.loaded.DASHBOARDS||[]).filter(r=>r.Nom===name&&String(r.Campagne_Code||"")===group).sort((a,b)=>Number(b.id)-Number(a.id))[0];if(match){rememberLastDashboard(match);document.querySelector('#builder-dashboard').value=String(match.id);document.querySelector('#builder-dashboard').dispatchEvent(new Event('change'))}document.querySelector('#status').innerHTML='<div class="status-info">Dashboard enregistré.</div>';setTimeout(()=>document.querySelector('#status').innerHTML='',1800)}
function configuredDashboardBlocks(){const cfg=dashboardConfig(state.dashboard);return normalizeDashboardTabs(cfg).flatMap(t=>t.blocks||[])}
function renderDashboardGlobal(){const cfg=dashboardConfig(state.dashboard),custom=configuredDashboardBlocks();if(!custom.length&&cfg.showIndividualResponses!==true)return originalRenderGlobal();const group=dashboardGroupRows(state.loaded?.CAMPAGNES||[]).find(g=>g.code===String(state.dashboard?.Campagne_Code||""))||{code:String(state.dashboard?.Campagne_Code||""),rows:state.campaigns,first:state.campaigns[0]};return `<div class="dash-grid" style="margin-top:14px">${renderBlocksFromConfig(cfg,group)||'<div class="dash-card">Aucun bloc configuré.</div>'}</div>`}
