async function load(){loadAdminModuleNav();const token=param('Dashboard_'),consultation=String(param('mode')||"").toLowerCase()==="view";if(consultation||token)state.responseScope="real";document.body.classList.toggle('dashboard-view-mode',consultation);if(!consultation&&!token){state.mode='builder';const loaded={};for(const t of TABLES){if(t==='DASHBOARDS')loaded[t]=await fetchDashboardTable();else if(t==='BIBLIOTHEQUE_REGROUPEMENTS'||t==='PERIODES_QUESTIONNAIRE'||t==='QUESTIONNAIRES'||t==='PAGES'||t==='SECTIONS'){try{loaded[t]=await fetch(t)}catch{loaded[t]=[]}}else loaded[t]=await fetch(t)}state.loaded=loaded;await reloadDashboardRows();document.querySelector('#status').innerHTML='';renderBuilder();return}state.mode='view';await loadViewer("",token,false);state.loaded=state.loaded||null}

